insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('78e4088f-3182-415b-a7aa-2f02964eda13', 'fcb1f534-a3e1-4135-a65f-e81c2cc3a889', $$bron 1: Romeinse kopie van de Griekse beelden van Harmodios en Aristogeiton (2e eeuw)$$,
   $$geschiedenis-vwo-2023-i-prehistorie-en-oudheid-bron1.png$$,
   $$bron 1 Een Romeinse kopie uit de tweede eeuw van Griekse beelden van Harmodios en Aristogeiton:
[Afbeelding] Foto van twee marmeren standbeelden van naakte mannen naast elkaar: links een bebaarde man met een mantel over zijn arm, rechts een jongere man met een geheven arm, klaar om toe te slaan.
Toelichting: Van de beelden die het Atheense stadsbestuur laat maken van Harmodios en Aristogeiton (zie vraag 2) worden in de Romeinse tijd vele kopieën gemaakt, die zijn gevonden in Romeinse villa''s.$$, 'inline'),
  ('48619ba4-56e2-40dc-9bdc-c4d7f8e979b5', '4243ca2b-5a69-4339-af23-3638f6ff56f4', $$bron 2: zilveren denarius met keizer Karel de Grote (omstreeks 812)$$,
   $$geschiedenis-vwo-2023-i-de-middeleeuwen-bron2.png$$,
   $$bron 2 Een zilveren denarius (munt) uit omstreeks 812, met een afbeelding van keizer Karel de Grote:
[Afbeelding] Foto van de voor- en achterkant van een zilveren munt: links een portret van een gekroonde keizer met een omschrift, rechts een tempelachtige kerk met een kruis en een omschrift.
Toelichting: Op de voorkant van de munt staat een portret van Karel de Grote met de Latijnse tekst Karolus Imp(erator) Aug(ustus): Karel, de verheven keizer. Op de achterkant van de munt staat een kerk met de tekst Xpictiana Religio: christelijke religie.$$, 'inline'),
  ('23d8c846-731c-4dc9-bb13-3977e51a3fa6', '4243ca2b-5a69-4339-af23-3638f6ff56f4', $$bron 3: oproep van paus Innocentius III tot oorlog tegen de Albigenzen (1208)$$,
   $$geschiedenis-vwo-2023-i-de-middeleeuwen-bron3.png$$,
   $$bron 3 In Occitanië (het zuiden van Frankrijk) wonen in de dertiende eeuw Albigenzen,christenen die er gebruiken op na houden die door de rooms- katholieke kerk worden afgewezen. Ze staan onder de bescherming van graaf Raymond VI van Toulouse. In 1208 begint paus Innocentius III een oorlog tegen de Albigenzen:
Wij verklaren allen die gebonden zijn aan de graaf van Toulouse door een belofte van trouw, bloedbanden of andere banden, volkomen vrij van hun verplichtingen. En geven toestemming aan alle katholieken om deze graaf te vervolgen, hem de landerijen af te nemen en deze zelf te bezitten, zonder daarbij de rechten van de soeverein [de Franse koning] aan te tasten. Soldaten van Christus, sta op! Roei deze goddeloosheid met alle middelen uit die God u geeft! Strek uw armen wijd uit en strijd dapper tegen de verspreiders van ketterij, pak hen harder aan dan de Saracenen1), want zij zijn veel slechter!
noot 1 Saracenen zijn moslims.$$, 'inline'),
  ('b25c7b7a-af31-43e9-b435-8080d8e01d4f', '35dc67ea-2884-4dd7-84fb-2a61219834aa', $$bron 4: bisschop Jakob van Vitry over de begijnen (begin 13e eeuw)$$,
   $$geschiedenis-vwo-2023-i-steden-en-burgers-1050-1700-bron4.png$$,
   $$bron 4 Aan het begin van de dertiende eeuw schrijft bisschop Jakob van Vitry over begijnen:
Wanneer een jonge vrouw de wens uitdrukt om haar maagdelijkheid te bewaren, dan zoeken en vinden haar ouders vlug een rijke jongeman die haar kan huwen. Ze moet die man verachten en verwerpen! (…) Helaas, vele leiders van de wereld, te weten wereldlijke prelaten1) en andere kwaadaardige lieden, proberen vaak dat meisje te vernietigen door te beletten dat ze haar vroom doel bereikt. En die lieden zeggen dan spottend: "Oh kijk eens daar! Zij wil een beguina2) zijn, want zo noemen ze die vrouwen in Vlaanderen en Brabant; of papelarda2), zo noemen ze hen in Frankrijk; of bizoke2), hun naam in Italië; of coquennune2), hun naam in Duitsland. Met dat soort van spot- en lasternamen proberen voorgenoemde lieden de maagden, die zich voorgenomen hebben de zuiverheid te bewaren, van hun heilige besluit af te brengen.
noot 1 Dit zijn geestelijken die gehoorzaamheid hebben beloofd aan een bisschop of paus.
noot 2 Dit zijn namen die ''een kletskous'' of ''een vrouw die gebedjes mompelt'' omschrijven.$$, 'inline'),
  ('8c01007d-a4c1-4b06-b60c-ee5a73fe1bbc', '35dc67ea-2884-4dd7-84fb-2a61219834aa', $$bron 6: pamflet van Amsterdamse burgers op de beurs (23 augustus 1672)$$,
   $$geschiedenis-vwo-2023-i-steden-en-burgers-1050-1700-bron6.png$$,
   $$bron 6 Amsterdamse burgers bevestigen op 23 augustus 1672 een pamflet aan een pilaar van het beursgebouw. Op dit pamflet staat:
Wij eisen:
− Dat de oude rechten hersteld worden.
− Dat de kapiteins van de schutterij die in het stadsbestuur zitten, worden afgezet [als kapitein] en worden vervangen door andere burgers.
− Dat niemand die in het stadsbestuur zit, bewindhebber zal worden van de Oost- of West-Indische Compagnie. (…)
Dit verzoek zal worden overgebracht aan zijne Hoogheid [stadhouder Willem III] en wanneer deze eisen niet zullen worden ingewilligd, zal er op zijn Haags1) worden opgetreden.
NB: Een ieder die dit pamflet zal verwijderen, zal de kogel krijgen, daar zal goed op worden toegezien.
Oranje wordt groot De Witten zijn dood (…)
noot 1 Hiermee wordt het lynchen van Johan en Cornelis de Witt in Den Haag bedoeld.$$, 'inline'),
  ('8e3e679b-b78e-4956-baef-9c272ffe4d7f', '23b9b1e6-24ba-4e64-bfcf-efc9e4d1c470', $$bron 7: prent van een Engels koffiehuis (17e eeuw)$$,
   $$geschiedenis-vwo-2023-i-verlichting-1650-1900-bron7.png$$,
   $$bron 7 In de zeventiende eeuw worden in Engeland honderden koffiehuizen geopend, waarvan deze prent er een toont:
[Afbeelding] Prent van het interieur van een druk koffiehuis: mannen met pruiken zitten aan tafels te lezen en te praten, een vrouw staat achter een toonbank en een jongen schenkt koffie in.
Toelichting: Op de tafels liggen kranten en pamfletten.$$, 'inline'),
  ('4307d598-f823-4977-9094-e766dda38e31', '5e06e256-4d79-4366-bc6d-4a70807bd8e6', $$bron 5: decreet van de katholieke kerk over aflaten (1563)$$,
   $$geschiedenis-vwo-2023-i-vroegmoderne-tijd-bron5.png$$,
   $$bron 5 Op 4 december 1563 vaardigt de katholieke kerk het volgende decreet uit over aflaten1):
Omdat de Kerk van Christus de volmacht heeft gekregen om aflaten te verlenen en zij van deze door God gegeven volmacht vanaf de oudste tijden gebruikmaakt. Zo leert en gebiedt de heilige Synode2) dat het gebruik van aflaten voor het christelijk volk hoogst heilzaam is en het door de autoriteit van heilige Concilies2) goedgekeurd is om voor de Kerk behouden te blijven. Het veroordeelt daarmee met de banvloek3) al diegene die of beweren dat aflaten van geen nut zijn, of die zeggen dat het niet aan de Kerkelijke macht toekomt hen te verlenen. Zij wenst echter dat men bij het verlenen van aflaten zich matigt en zich erop toelegt de kerkelijke orde niet door al te grote plooibaarheid schade te berokkenen. Zij wenst dat de misbruiken die ingeslopen zijn (…) worden vermeden en gecorrigeerd, zo bepaalt zij door het voorliggende decreet in het algemeen dat al de oneigenlijke winst voor het verkrijgen van een aflaat volledig afgeschaft moet worden.
noot 1 Een aflaat is een kwijtschelding voor straf van God. Gelovigen kunnen een aflaat verkrijgen door goede werken te verrichten of door geld te betalen. noot 2 Een Synode en een Concilie zijn kerkvergaderingen. noot 3 Een banvloek houdt in dat een gelovige wordt buitengesloten.$$, 'inline'),
  ('d21026b3-4d6a-4542-ad41-b6631b0483c5', '70d32c6d-6850-4f99-9974-af33e3421a09', $$bron 8: prent De situatie in het Verre Oosten van Tse Tsan-tai (1899)$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-bron8.png$$,
   $$bron 8 In 1899 publiceert Tse Tsan-tai deze prent met de titel De situatie in het Verre Oosten:
[Afbeelding] Prent met een kaart van China en omgeving waarop dieren staan: bovenaan een grote beer, daaronder een buldog, een kikker en rechtsonder een adelaar; in de linkerbovenhoek staan Chinese tekens.
Toelichting: Op de kaart van China zijn dieren afgebeeld die symbool staan voor verschillende landen, namelijk (van boven naar beneden) de Russische beer, de Britse buldog, de Franse kikker en rechtsonder de Amerikaanse adelaar.$$, 'inline'),
  ('5273ec21-3352-442e-ba27-afa52a4c710e', '70d32c6d-6850-4f99-9974-af33e3421a09', $$bron 13: poster met 'honderd aandachtspunten' bij een middenschool in Peking (1966)$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-bron13.png$$,
   $$bron 13 In augustus 1966 wordt een poster met ''honderd aandachtspunten'' opgeplakt bij de Nr. 26 Middenschool in Peking. Enkele van de aandachtspunten zijn:
− Wij bevelen jullie onmiddellijk om je bluejeans weg te werpen, je vettig haar te scheren, je flitsende schoenen uit te trekken.
− Het houden van vissen, katten en honden en vergelijkbare bourgeoisgewoonten mogen niet langer bestaan onder het Chinese volk.
− Het dragen van feodale versierselen als armbanden, oorringen enz. is verboden.
− De school krijgt als nieuwe naam ''De Maoïstische school''.$$, 'inline'),
  ('08c1f485-a335-4847-a8be-153efe24a5d1', '70d32c6d-6850-4f99-9974-af33e3421a09', $$bron 14: rapport van de Staatssicherheitsdienst over een Chinese fototentoonstelling in Oost-Berlijn (1967)$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-bron14.png$$,
   $$bron 14 In februari 1967 stelt de Chinese ambassade in Oost-Berlijn foto''s tentoon in vitrines aan de buitenkant van het gebouw. De Staatssicherheitsdienst schrijft hierover in een rapport aan de minister van Staatsveiligheid van de DDR:
De getoonde afbeeldingen laten Chinese studenten zien die voorlezen uit de "werken" van Mao (…) op het Rode Plein in Moskou en er zijn foto''s van Sovjetmilities en burgers die ingrijpen, dus van een beginnende confrontatie. Verder zijn er in scène gezette beelden van gewonde en bloedende Chinezen te zien. Elk van die afbeeldingen is becommentarieerd met duidelijk lasterlijke anti-Sovjet-bijschriften, bijvoorbeeld:
1 "Deze burger raakte ernstig gewond door trappen op zijn borst van Sovjetagenten; zijn toestand is levensbedreigend."
2 "Slachtoffer van de fascistische bloedige daad van de Sovjetrevisionisten."
(…)
Het viel op dat na het inrichten van deze vitrines de voorbijgangers meer dan gebruikelijk aandacht besteedden aan de tentoongestelde materialen.$$, 'inline'),
  ('0e7b50f4-7adb-444d-ba8c-4a5db18ee8de', '09de3efe-bfd4-466e-85ea-da59120a5a35', $$inleiding vraag 20: toestemming voor zendtijd aan de CPN (1965)$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-context1.png$$,
   $$In september 1965 geeft de Nederlandse regering voor het eerst toestemming aan de Communistische Partij Nederland (CPN) voor zendtijd op radio en televisie.$$, 'inline'),
  ('20419c3c-0d9f-4d72-96bd-680139cb5230', '09de3efe-bfd4-466e-85ea-da59120a5a35', $$bron 11: foto van Hugo Wilmar van Nederlandse mariniers in Nederlands-Indië (1946)$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-bron11.png$$,
   $$bron 11 In 1946 maakt de Nederlandse marinier Hugo Wilmar deze foto in Nederlands-Indië (Indonesië):
[Afbeelding] Zwart-witfoto: gewapende soldaten rennen langs een brandend dorp met houten huizen waaruit dikke rookwolken opstijgen.
Toelichting: De mannen zijn Nederlandse mariniers. Op de achtergrond is een brandende kampong, een Indonesisch dorp, te zien.$$, 'inline'),
  ('d6760de4-f095-487e-b0da-06790034ce70', '09de3efe-bfd4-466e-85ea-da59120a5a35', $$bron 12: prent Binnenkort ook op tv reclamespots door: Paulus de Moskou-bouter van Fritz Behrendt (1965)$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-bron12.png$$,
   $$bron 12 In 1965 verschijnt deze prent van Fritz Behrendt in het Algemeen Handelsblad met de titel Binnenkort ook op tv reclamespots door: Paulus de Moskou-bouter:
[Afbeelding] Spotprent: een man zit op een boomstronk een boek te lezen voor een televisiecamera, terwijl boven hem een microfoon hangt.
Toelichting: Boven de microfoon staat NRU / NTS (Nederlandse Radio Unie / Nederlandse Televisie Stichting). Op de boomstronk zit Paul de Groot, voorzitter van de Communistische Partij Nederland. De titel van het boek is Sprookjes van de Marx-Brothers; op het boek staan Stalin en Mao Zedong afgebeeld. Vanaf 1955 wordt op de radio dagelijks voor kinderen het hoorspel Paulus de Boskabouter uitgezonden.$$, 'inline'),
  ('e3209c54-d793-4e29-b8f1-0ad72800041d', '3477e1a2-1bdb-41b3-ade6-b90310e39aee', $$bron 9: Eliza von Moltke over haar overleden echtgenoot Helmuth von Moltke (1922)$$,
   $$geschiedenis-vwo-2023-i-duitsland-in-europa-1918-1991-bron9.png$$,
   $$bron 9 Helmuth von Moltke (1848-1916) is in augustus 1914 opperbevelhebber van het Duitse leger. Zes weken na de start van de Eerste Wereldoorlog wordt hij uit zijn functie ontheven. In 1922 schrijft zijn weduwe Eliza von Moltke in een boek over haar inmiddels overleden echtgenoot:
De Vrede van Versailles waarin het artikel over schuld door de Duitse onderhandelaars is ondertekend, heeft het grootste onheil over Duitsland en de wereld gebracht. In Duitsland is ondertussen uitgebreid geschreven over de oorzaken van het verlies van de oorlog. Steeds weer wordt gewezen op de Slag bij de Marne1) en het falen van het opperbevel van het [Duitse] leger en in het bijzonder op de vermeende onbekwaamheid van Moltke. (…) Dit soort zinnen dwingen me om dit boek uit te geven. (…) Moltkes plan om nieuwe aanvallen te beginnen, nadat het leger door de terugtocht bij de Marne meer bewegingsvrijheid had gekregen, werd onder leiding van generaal Von Falkenhayn2) niet uitgevoerd. In plaats daarvan begon de loopgravenoorlog die Moltke koste wat het kost had willen vermijden, omdat hij wist hoe groot het gevaar voor het Duitse leger zou zijn.
noot 1 De Marne is een rivier in Noord-Frankrijk. noot 2 Generaal Von Falkenhayn volgde Von Moltke op.$$, 'inline'),
  ('abd7ef95-9793-4ec3-9a73-3314a973030a', '3477e1a2-1bdb-41b3-ade6-b90310e39aee', $$bron 10: persinstructie van de Duitse regering over de Sudeten-Duitsers (1938)$$,
   $$geschiedenis-vwo-2023-i-duitsland-in-europa-1918-1991-bron10.png$$,
   $$bron 10 Op 14 september 1938 krijgt de Duitse pers deze instructie voor de berichtgeving over spanningen tussen de Tsjecho-Slowaakse bevolking en de Sudeten-Duitsers (een Duitstalige minderheid in Tsjecho-Slowakije):
In de Tsjecho-Slowaakse kwestie moet op dezelfde manier te werk worden gegaan als vanmorgen: in een opmaak met grote letters en in de scherpste bewoordingen. Breng het bericht over de dertien dodelijke slachtoffers bij de Sudeten-Duitsers en de vier doden aan de Tsjechische kant groot naar buiten. Het medeleven van de gehele Duitse Volksgemeinschaft moet uitgesproken worden. (…) In de hoofdartikelen kan het idee van een referendum worden behandeld en wel als volgt: na al deze onlusten is het nauwelijks voorstelbaar dat een vreedzaam samenleven van bevolkingsgroepen in één staat mogelijk is.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('318a00ff-17d1-4474-8d02-6ff1b5b649c5', '65b7e86c-62f6-4e84-80b1-892db9d590a4', 1,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Verlichting", "subdomain": "Democratische revoluties in de VS en Frankrijk (1776-1813)"}]'::jsonb,
   '["chronologie", "slavernij", "trans-Atlantische slavenhandel", "kerstening", "Europese overzeese expansie", "Haïtiaanse Revolutie"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen uit het leven van slaafgemaakten in verschillende tijdvakken.$$,
   $$geschiedenis-vwo-2023-i-door-de-tijd-heen-vraag1.png$$, $$De volgende gebeurtenissen in het leven van slaafgemaakten staan in willekeurige volgorde:
1 Aan het einde van de Gouden Eeuw wilden Algerijnse kapers de opvarenden van een Zeeuws schip op een slavenmarkt in Tunis verkopen.
2 Caius Paternus verleende de slaafgemaakte Iustina de vrijheid om daarna met haar te trouwen in de Romeinse provincie Gallia Transalpina.
3 Dutty Boukman voerde kort na het begin van de Franse Revolutie een voodoo-ritueel uit waarmee hij de slaafgemaakten in de Franse kolonie Saint-Domingue opriep de wapens op te nemen.
4 In het archief van Francesco Datini, een koopman tijdens de bloei van de Italiaanse stadstaat Prato, bevond zich een document waarin een slavin voor 50 florijnen werd verzekerd tegen ongelukken maar niet tegen vluchtpogingen.
5 Kort na de ontdekking van Amerika nam Pedro de las Casas de slaafgemaakte jongen Juanico mee als cadeau voor zijn zoon Bartolomé.
6 Na zijn vlucht uit Ierland keerde de voormalige slaafgemaakte veehoeder Patrick terug, om de Ierse bevolking tot het christendom te bekeren. 2p 1 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('1c5daabf-90a7-4f19-9de8-456ae671a647', '65b7e86c-62f6-4e84-80b1-892db9d590a4', 12,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Opkomst van de stedelijke burgerij (1050-1302)"}, {"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij en centralisatie (1302-1602)"}, {"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij in de Gouden Eeuw (1602-1700)"}]'::jsonb,
   '["chronologie", "Hanze", "infrastructuur", "Napoleon", "regenten", "spoorwegen"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen rond Nederlandse wegen uit verschillende tijdvakken.$$,
   $$geschiedenis-vwo-2023-i-door-de-tijd-heen-vraag12.png$$, $$De volgende gebeurtenissen, die te maken hebben met Nederlandse wegen, staan in willekeurige volgorde:
1 Bij de aanleg van een weg tussen Amersfoort en Utrecht werden aan weerszijden percelen aangewezen waarop regenten hun nieuwe buitenhuizen lieten aanleggen.
2 De pachters van tolwegen klaagden dat hun opbrengsten daalden na de aanleg van de eerste spoorlijnen.
3 In Gelderland ontstonden ''Hanzewegen'', toen handelaren tussen verschillende Hanzesteden begonnen te reizen.
4 Keizer Napoleon Bonaparte besloot dat in Nederland een netwerk van verharde wegen moest worden aangelegd. De eerste 28 rijkswegen zouden naar Parijs worden doorgetrokken.
5 Nadat Atrecht een lokale marktfunctie kreeg, ontstond een steeds fijner netwerk van wegen tussen Atrecht en haar verzorgingsgebied.
6 Op de wegen rondom ''s-Hertogenbosch werd tijdens de regering van koning Philips II alleen tol betaald door koopmannen die van buiten ''s-Hertogenbosch kwamen. 2p 12 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('96c818d0-bcd2-4f6d-8460-db09789dc8ba', 'fcb1f534-a3e1-4135-a65f-e81c2cc3a889', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}]'::jsonb,
   '["Atheense democratie", "tirannie", "Griekse stadstaat", "burgerschap", "politiek motief", "religie"]'::jsonb,
   $$Uitleggen welk politiek motief Athene had om standbeelden van Harmodios en Aristogeiton te plaatsen en hoe offers het politieke denken beïnvloedden.$$,
   $$geschiedenis-vwo-2023-i-prehistorie-en-oudheid-vraag2.png$$, $$In 514 voor Christus doodden de Atheense burgers Harmodios en Aristogeiton de alleenheerser Hipparchos. Enkele jaren daarna besloot het stadsbestuur op het centrale plein in Athene standbeelden van Harmodios en Aristogeiton te plaatsen en legde vast dat elk jaar offers moesten worden gebracht bij deze beelden. 3p 2 Licht dit besluit toe door:
− aan te geven welk politiek motief het Atheense stadsbestuur had om beelden van juist deze mannen te laten plaatsen, en
− uit te leggen dat door te laten offeren bij de beelden het stadsbestuur het denken over politiek in de stadstaat beïnvloedde.$$, array[]::uuid[]),
  ('ec7470b5-712a-4873-9b2f-1a5261bd8c89', 'fcb1f534-a3e1-4135-a65f-e81c2cc3a889', 3,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}]'::jsonb,
   '["klassieke vormentaal", "Romeinse rijk", "verspreiding Grieks-Romeinse cultuur", "beeldhouwkunst", "kenmerkend aspect", "romanisering"]'::jsonb,
   $$Twee kenmerkende aspecten van de Romeinse oudheid noemen die je met een Romeinse kopie van Griekse beelden illustreert.$$,
   $$geschiedenis-vwo-2023-i-prehistorie-en-oudheid-vraag3.png$$, $$Gebruik bron 1. Met deze Romeinse kopie van de beelden kun je twee kenmerkende aspecten uit de tijd van de Romeinse Oudheid illustreren. 2p 3 Noem deze twee kenmerkende aspecten.$$, array['78e4088f-3182-415b-a7aa-2f02964eda13']::uuid[]),
  ('54f1aefc-c9de-463a-9713-d1a2351ba00e', '4243ca2b-5a69-4339-af23-3638f6ff56f4', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Monniken en ridders (500-1000)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}]'::jsonb,
   '["Karel de Grote", "keizerskroning", "Romeinse rijk", "kerstening", "propaganda herkennen", "Karolingische rijk"]'::jsonb,
   $$Uitleggen welke politieke continuïteit en eenheid Karel de Grote met de afbeeldingen op een munt suggereerde.$$,
   $$geschiedenis-vwo-2023-i-de-middeleeuwen-vraag4.png$$, $$Gebruik bron 2. Twaalf jaar nadat Karel de Grote tot keizer is gekroond, laat hij deze munt slaan. Twee interpretaties:
1 Karel suggereert een bepaalde politieke continuïteit.
2 Karel streeft naar eenheid in zijn rijk. 3p 4 Geef aan:
− welke politieke continuïteit Karel met de voorkant van de munt suggereert, en
− welke boodschap Karel wil overbrengen door het suggereren van deze politieke continuïteit, en
− dat Karel met de achterkant van de munt streeft naar eenheid in zijn rijk.$$, array['48619ba4-56e2-40dc-9bdc-c4d7f8e979b5']::uuid[]),
  ('ca347e03-5a39-4d59-a76b-5163ff7a149e', '4243ca2b-5a69-4339-af23-3638f6ff56f4', 5,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Steden en staten — overig (1000-1500)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Monniken en ridders (500-1000)"}]'::jsonb,
   '["kruistochten", "feodale verhoudingen", "ketterij", "Innocentius III", "wereldlijke en geestelijke macht", "kenmerkend aspect"]'::jsonb,
   $$Uitleggen hoe paus Innocentius III feodale verhoudingen inzette tegen de Albigenzen en de oorlog vergeleek met de kruistochten.$$,
   $$geschiedenis-vwo-2023-i-de-middeleeuwen-vraag5.png$$, $$Gebruik bron 3. Deze oproep tot strijd tegen de Albigenzen past bij verschillende kenmerkende aspecten van de middeleeuwen. 3p 5 Geef aan:
− op welke wijze de paus bestuurlijke verhoudingen uit de vroege middeleeuwen inzet tegen graaf Raymond, waarbij je je antwoord ondersteunt met een kenmerkend aspect uit de vroege middeleeuwen, en
− met een kenmerkend aspect uit de late middeleeuwen met welke strijd de paus de oorlog tegen de Albigenzen vergelijkt.$$, array['23d8c846-731c-4dc9-bb13-3977e51a3fa6']::uuid[]),
  ('66d3ca9d-0e35-42eb-befd-963c0b8b1382', '35dc67ea-2884-4dd7-84fb-2a61219834aa', 6,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Opkomst van de stedelijke burgerij (1050-1302)"}]'::jsonb,
   '["begijnen", "betrouwbaarheid", "bruikbaarheid", "standplaatsgebondenheid", "stedelijke samenleving", "religieuze bewegingen"]'::jsonb,
   $$Verklaren dat een bron over begijnen bruikbaar is voor hun verspreiding maar minder betrouwbaar over hun motieven.$$,
   $$geschiedenis-vwo-2023-i-steden-en-burgers-1050-1700-vraag6.png$$, $$Gebruik bron 4. Stel: een onderzoek naar de beweging van de begijnen heeft twee onderzoeksgebieden:
1 De verspreiding van de beweging van de begijnen in Europa.
2 De motieven van vrouwen om toe te treden tot de beweging van de begijnen. De bron wordt alleen gebruikt voor de eerste deelvraag. 3p 6 Verklaar dit door:
− aan te geven dat je de bron kunt gebruiken voor het eerste onderzoeksgebied, en
− uit te leggen dat de bron minder betrouwbare informatie bevat voor het tweede onderzoeksgebied.$$, array['b25c7b7a-af31-43e9-b435-8080d8e01d4f']::uuid[]),
  ('419ca93f-eb8a-44cf-b97d-560277724cbf', '35dc67ea-2884-4dd7-84fb-2a61219834aa', 7,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Opkomst van de stedelijke burgerij (1050-1302)"}]'::jsonb,
   '["patriciërs", "stedelijke burgerij", "Vlaamse steden", "Brugge", "graaf van Vlaanderen", "Guldensporenslag"]'::jsonb,
   $$Aangeven dat de kritiek van de Franse koningin op de Brugse patriciërs een politieke en een sociale achtergrond had.$$,
   $$geschiedenis-vwo-2023-i-steden-en-burgers-1050-1700-vraag7.png$$, $$In 1301 zou de Franse koningin Johanna tijdens een bezoek aan Brugge zich hebben geërgerd aan de ''onmatige pracht en praal van de Brugse vrouwen'' en hebben uitgeroepen: "Ik dacht dat alleen ik koningin was en ik vind er hier honderden." De koningin geeft met haar uitroep kritiek op een verandering in de levensstijl van de Brugse patriciërs in de late middeleeuwen. 2p 7 Geef aan dat de kritiek van de koningin een politieke en een sociale achtergrond had.$$, array[]::uuid[]),
  ('2d20d8d4-4a21-41b5-8dad-9c83adb1d60f', '35dc67ea-2884-4dd7-84fb-2a61219834aa', 9,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij in de Gouden Eeuw (1602-1700)"}]'::jsonb,
   '["Rampjaar 1672", "Oranjegezind", "staatsgezind", "Johan de Witt", "regenten", "stadhouder"]'::jsonb,
   $$Met een pamflet uit 1672 de politieke tegenstelling in de Republiek en de kritiek van Amsterdamse burgers aantonen.$$,
   $$geschiedenis-vwo-2023-i-steden-en-burgers-1050-1700-vraag9.png$$, $$Gebruik bron 6. Met dit pamflet kun je een politiek conflict illustreren dat in 1672 speelt in de Republiek. 3p 9 Toon dit aan door:
− de politieke tegenstelling uit die tijd te noemen, waarbij je je antwoord ondersteunt met een verwijzing naar de bron, en
− aan te geven op welk politiek probleem de Amsterdamse burgers in dit pamflet kritiek leveren.$$, array['8c01007d-a4c1-4b06-b60c-ee5a73fe1bbc']::uuid[]),
  ('462f35fc-321b-46e0-9904-3fff553bac38', '23b9b1e6-24ba-4e64-bfcf-efc9e4d1c470', 10,
   '[{"domain": "Verlichting", "subdomain": "Verlichte ideeën over een rechtvaardige samenleving (1650-1789)"}, {"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij in de Gouden Eeuw (1602-1700)"}]'::jsonb,
   '["publieke opinie", "politieke cultuur", "koffiehuizen", "Karel II", "absolutisme", "pamfletten"]'::jsonb,
   $$Uitleggen hoe koffiehuizen het denken over politiek beïnvloedden en waarom Karel II ze wilde sluiten.$$,
   $$geschiedenis-vwo-2023-i-verlichting-1650-1900-vraag10.png$$, $$Gebruik bron 7. In 1675 wil koning Karel II de koffiehuizen in Engeland laten sluiten. 3p 10 Verklaar dit door:
− met een verwijzing naar de prent uit te leggen waardoor de koffiehuizen het denken over politiek beïnvloeden, en
− aan te geven welk politiek motief Karel II heeft om de koffiehuizen te sluiten.$$, array['8e3e679b-b78e-4956-baef-9c272ffe4d7f']::uuid[]),
  ('66bc40ef-d8b3-4297-b282-e4a5494fc9aa', '23b9b1e6-24ba-4e64-bfcf-efc9e4d1c470', 11,
   '[{"domain": "Verlichting", "subdomain": "Verlichte ideeën over een rechtvaardige samenleving (1650-1789)"}]'::jsonb,
   '["verlicht denken", "rationalisme", "Encyclopédie", "absolutisme", "goddelijk recht", "kritiek op het ancien régime"]'::jsonb,
   $$Uitleggen dat een beschrijving in de Encyclopédie het absolutisme bekritiseerde en paste bij het rationalisme.$$,
   $$geschiedenis-vwo-2023-i-verlichting-1650-1900-vraag11.png$$, $$In Engeland en Frankrijk bestond de gewoonte dat de koning op bepaalde feestdagen de lijders aan scrofulose (een ontsteking in de hals) aanraakte om hen te genezen. In de Encyclopédie die in 1755 is uitgegeven stond hierover: "Als de hemel een dergelijke macht aan koningen zou hebben verleend, dan zou men verwachten dat dit voor iedereen zichtbaar was en dat de genezing toch op zijn minst af en toe meteen na de aanraking optrad." 3p 11 Licht dit toe door:
− aan te tonen op welke wijze deze beschrijving het absolutisme bekritiseerde, en
− uit te leggen dat de redenering in de Encyclopédie paste bij het rationalisme.$$, array[]::uuid[]),
  ('17e4d939-3fc0-476b-96d9-2499ddc1bb15', '23b9b1e6-24ba-4e64-bfcf-efc9e4d1c470', 13,
   '[{"domain": "Verlichting", "subdomain": "Verlichtingsideeën in de Europese politieke cultuur (1813-1900)"}]'::jsonb,
   '["afscheiding België", "Congres van Wenen", "Oranje-Nassau", "Willem I", "nationalisme", "monarchie"]'::jsonb,
   $$Uitleggen waarom het Belgische Nationaal Congres in 1830 koos voor een monarchie en het huis Oranje-Nassau uitsloot.$$,
   $$geschiedenis-vwo-2023-i-verlichting-1650-1900-vraag13.png$$, $$In november 1830 stemde het Nationaal Congres van de nieuwe staat België over verschillende kwesties:
1 Het Congres stemde in met het voorstel dat België een monarchie werd.
2 Het Congres nam een grondwettelijke tekst aan met daarin de bepaling "dat de leden van het stamhuis van Oranje-Nassau voor altijd uit alle macht of gezag in België uitgesloten zijn". 3p 13 Licht de bepalingen toe door:
− uit te leggen waardoor het Congres verwachtte dat de eerste bepaling noodzakelijk was voor de acceptatie van de nieuwe staat België door Europese mogendheden, en
− een binnenlands-politieke verklaring te geven voor het afwijzen van de leden van het stamhuis van Oranje-Nassau.$$, array[]::uuid[]),
  ('90fc89d4-a501-4e39-a616-08ec1f605a24', '5e06e256-4d79-4366-bc6d-4a70807bd8e6', 8,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij en centralisatie (1302-1602)"}]'::jsonb,
   '["Reformatie", "Contrareformatie", "aflaten", "Concilie van Trente", "katholieke kerk", "bronverwijzing"]'::jsonb,
   $$Aangeven op welke twee manieren de katholieke kerk met een decreet over aflaten de protestantse reformatie wilde tegengaan.$$,
   $$geschiedenis-vwo-2023-i-vroegmoderne-tijd-vraag8.png$$, $$Gebruik bron 5 4p 8 Geef aan op welke twee verschillende manieren de katholieke kerk met dit decreet de protestantse reformatie wil tegengaan, waarbij je telkens je antwoord ondersteunt met een andere verwijzing naar de bron.$$, array['4307d598-f823-4977-9094-e766dda38e31']::uuid[]),
  ('fffa529a-8b1c-451d-9d18-bc9ffac93eca', '70d32c6d-6850-4f99-9974-af33e3421a09', 15,
   '[{"domain": "China", "subdomain": "Verlies van regionale grootmacht (1842-1911)"}]'::jsonb,
   '["modern imperialisme", "invloedssferen", "Qing-dynastie", "Hongkong", "spotprent", "ongelijke verdragen"]'::jsonb,
   $$Uitleggen welke kritiek Tse Tsan-tai met een prent op de Chinese regering gaf en waarom hij die in Hongkong kon publiceren.$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-vraag15.png$$, $$Gebruik bron 8. Tse Tsan-tai is een Chinese uitgever die zich in Hongkong vestigt. Met deze prent geeft hij kritiek weer op de Chinese regering. 3p 15 Toon dit aan door:
− met de bron uit te leggen welke kritiek op de regering Tse weergeeft, en
− zonder bron te verklaren waardoor Tse deze prent kan publiceren in Hongkong.$$, array['d21026b3-4d6a-4542-ad41-b6631b0483c5']::uuid[]),
  ('4841dded-4c58-4684-835a-50d9de1eb1ec', '70d32c6d-6850-4f99-9974-af33e3421a09', 22,
   '[{"domain": "China", "subdomain": "Ontwikkeling tot grootmacht (1949-2001)"}]'::jsonb,
   '["Culturele Revolutie", "Rode Gardisten", "Mao Zedong", "bourgeois", "Vier Ouden", "klassenstrijd"]'::jsonb,
   $$Twee kenmerken van de Culturele Revolutie noemen met aandachtspunten van een poster uit 1966.$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-vraag22.png$$, $$Gebruik bron 13. Deze aandachtspunten passen bij de Culturele Revolutie. 4p 22 Noem twee kenmerken van de Culturele Revolutie waarbij deze aandachtspunten passen, waarbij je je antwoord telkens ondersteunt met een verwijzing naar een ander aandachtspunt. Let op: je mag een aandachtspunt maar één keer gebruiken.$$, array['5273ec21-3352-442e-ba27-afa52a4c710e']::uuid[]),
  ('cbd98e9f-c41a-4d8a-b913-f00ea51ad170', '70d32c6d-6850-4f99-9974-af33e3421a09', 23,
   '[{"domain": "China", "subdomain": "Ontwikkeling tot grootmacht (1949-2001)"}]'::jsonb,
   '["breuk met de Sovjet-Unie", "DDR", "Staatssicherheitsdienst", "propaganda herkennen", "Koude Oorlog", "communistisch blok"]'::jsonb,
   $$Uitleggen welke boodschappen China en de DDR uitdroegen met een fototentoonstelling in Oost-Berlijn en het weghalen ervan.$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-vraag23.png$$, $$Gebruik bron 14. Kort nadat de Chinese ambassade in Oost-Berlijn de fototentoonstelling laat inrichten, haalt de Staatssicherheitsdienst deze weg. 3p 23 Geef aan:
− welke ideologische boodschap China wil overbrengen aan de regering van de DDR met de fototentoonstelling, waarbij je je antwoord ondersteunt met een verwijzing naar de bron, en
− welke politieke boodschap de regering van de DDR overbrengt door de fototentoonstelling weg te halen.$$, array['08c1f485-a335-4847-a8be-153efe24a5d1']::uuid[]),
  ('6d2b13dd-97f1-47c2-8c00-3643894373a4', '70d32c6d-6850-4f99-9974-af33e3421a09', 24,
   '[{"domain": "China", "subdomain": "Ontwikkeling tot grootmacht (1949-2001)"}]'::jsonb,
   '["Jiang Zemin", "Deng Xiaoping", "Vier Moderniseringen", "Plein van de Hemelse Vrede", "economische hervormingen", "politieke continuïteit"]'::jsonb,
   $$Uitleggen welke ontwikkeling Jiang Zemin benadrukte en welke politieke continuïteit hij met zijn uitspraak onderbouwde.$$,
   $$geschiedenis-vwo-2023-i-china-1842-2001-vraag24.png$$, $$In 1997 zei Jiang Zemin: "Het is belangrijk om de verhouding tussen ontwikkeling aan de ene kant en stabiliteit aan de andere kant zo goed mogelijk te beheersen, en zo een stabiele politieke en sociale samenleving te behouden. Zonder stabiliteit kan niets bereikt worden." 3p 24 Licht deze uitspraak toe door:
− de ontwikkeling te noemen waarop Zemin in zijn beleid in China de nadruk legde, en
− uit te leggen welke politieke continuïteit in China Zemin met deze uitspraak wilde onderbouwen.$$, array[]::uuid[]),
  ('ca73ebb1-96cf-4f11-b759-ee248dfce3e3', '09de3efe-bfd4-466e-85ea-da59120a5a35', 14,
   '[{"domain": "Verlichting", "subdomain": "Verlichtingsideeën in de Europese politieke cultuur (1813-1900)"}]'::jsonb,
   '["feminisme", "socialisme", "emancipatie", "arbeidersbeweging", "Clara Zetkin", "vrouwenbeweging"]'::jsonb,
   $$Aangeven bij welke sociale klasse de feministische beweging aanhang had en welke koerswijziging Clara Zetkin wilde.$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-vraag14.png$$, $$Hoofdredactrice Clara Zetkin schreef in 1898 in het Duitse tijdschrift Die Gleichheit (Gelijkheid): "Een tijdschrift als Die Gleichheit kan geen beweging veroorzaken [bij vrouwelijke arbeiders] maar kan werken binnen die beweging, door scholing en aanmoediging te geven; en dat heeft Die Gleichheit gedaan. Die Gleichheit heeft als hoofddoel de vrouwelijke kameraden aan te spreken die in de frontlinie staan bij onze strijd." Clara Zetkin wil met Die Gleichheit de koers van de Duitse feministische beweging veranderen. 2p 14 Geef aan:
− onder welke sociale klasse de feministische beweging in de negentiende eeuw vooral aanhang kreeg, en
− welke koersverandering Clara Zetkin wil bevorderen.$$, array[]::uuid[]),
  ('7091f98e-759d-4d42-9dbc-7c71c66fe9b5', '09de3efe-bfd4-466e-85ea-da59120a5a35', 18,
   '[{"domain": "China", "subdomain": "Ontwikkeling tot grootmacht (1949-2001)"}]'::jsonb,
   '["dekolonisatie", "Indonesische onafhankelijkheidsoorlog", "politionele acties", "censuur", "bruikbaarheid", "Nederlands-Indië"]'::jsonb,
   $$Verklaren waarom een foto uit Nederlands-Indië werd afgekeurd en uitleggen dat hij bruikbaar is voor onderzoek naar de dekolonisatieoorlog.$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-vraag18.png$$, $$Gebruik bron 11. Twee gegevens:
1 Deze foto wordt door de Nederlandse legervoorlichtingsdienst afgekeurd voor publicatie.
2 Hugo Wilmar schrijft in 1946 aan zijn ouders: "Wat de publicatie [van zijn foto''s] betreft: deze wordt zoveel mogelijk geblokkeerd en tegengegaan. Schandelijk! Het Nederlandse Volk leeft daarom in de stellige overtuiging dat we hier rustig in ons mooie Indië zitten en toch maar boffen." Je gebruikt deze foto voor een onderzoek naar de dekolonisatieoorlog in Indonesië. 3p 18 Licht je keuze toe door:
− een verklaring te geven voor het besluit van de Nederlandse legervoorlichtingsdienst deze foto voor publicatie af te keuren (gegeven 1), en
− uit te leggen dat je de foto bruikbaar vindt voor je onderzoek, waarbij je je antwoord ondersteunt met gegeven 2.$$, array['20419c3c-0d9f-4d72-96bd-680139cb5230']::uuid[]),
  ('27e6a948-8666-4a4c-9996-fcdd56079956', '09de3efe-bfd4-466e-85ea-da59120a5a35', 20,
   '[{"domain": "Duitsland in Europa", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Koude Oorlog", "communisme", "spotprent", "CPN", "televisie", "bronverwijzing"]'::jsonb,
   $$Aangeven welke visie Behrendt met een prent gaf op de toestemming voor zendtijd aan de CPN in 1965.$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-vraag20.png$$, $$Gebruik bron 12.
2p 20 Geef aan welke visie Behrendt op deze toestemming weergeeft, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['0e7b50f4-7adb-444d-ba8c-4a5db18ee8de', 'd6760de4-f095-487e-b0da-06790034ce70']::uuid[]),
  ('c2921dca-8462-4af1-93bc-607535be34b7', '09de3efe-bfd4-466e-85ea-da59120a5a35', 21,
   '[{"domain": "Duitsland in Europa", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["detente", "jaren zestig", "gezagsverhoudingen", "democratisering", "Koude Oorlog", "CPN"]'::jsonb,
   $$Uitleggen hoe detente en het veranderende denken over autoriteit het geven van zendtijd aan de CPN verklaren.$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-vraag21.png$$, $$Volgens sommige historici kan het besluit om de CPN zendtijd te geven (zie vraag 20) worden verklaard vanuit:
1 de detente.
2 de verandering in het denken over autoriteit in de jaren 1960. 4p 21 Leg voor beide de redenering van de historici uit.$$, array['0e7b50f4-7adb-444d-ba8c-4a5db18ee8de']::uuid[]),
  ('4b822860-b0fb-4c26-9dcb-02de72212c4d', '09de3efe-bfd4-466e-85ea-da59120a5a35', 25,
   '[{"domain": "Verlichting", "subdomain": "Verlichtingsideeën in de Europese politieke cultuur (1813-1900)"}, {"domain": "Duitsland in Europa", "subdomain": "Opkomst nationaalsocialisme en Tweede Wereldoorlog (1918-1945)"}, {"domain": "Duitsland in Europa", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["kenmerkend aspect", "eenwording Duitsland", "Tweede Wereldoorlog", "sociaal-culturele veranderingen", "homo-emancipatie", "Berlijn"]'::jsonb,
   $$Bij drie gebeurtenissen rond de Siegessäule het passende kenmerkende aspect noemen.$$,
   $$geschiedenis-vwo-2023-i-moderne-tijd-vraag25.png$$, $$Drie gebeurtenissen bij de Siegessäule (de overwinningszuil), een monument in Berlijn:
1 In september 1873 marcheerden Duitse troepen triomfantelijk langs de Siegessäule, waarin kanonnen waren verwerkt die zij buit hadden gemaakt.
2 In mei 1945 hesen Poolse troepen na de overwinning in de Slag om Berlijn hun vlag in de top van de Siegessäule.
3 In juni 1979 werd de Siegessäule opgenomen in de route van een parade waarin aandacht werd gevraagd voor de rechten van homoseksuelen. 3p 25 Noem bij elke gebeurtenis het kenmerkende aspect van die tijd dat hierbij past. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('8d115c2c-5d58-4ee9-aeb5-51659b5bb047', '3477e1a2-1bdb-41b3-ade6-b90310e39aee', 16,
